<?php
namespace Tapin\ServicePointLocator\PriceCheck;
use Tapin\ServicePointLocator\PriceCheck\PythonValue as V;
defined( 'ABSPATH' ) || exit;

/** Source admin log/cache/security API. Authorization belongs to both REST boundary checks. */
final class OperationalApiService {
	const OPERATIONS = array( 'admin_list_logs', 'admin_clear_logs', 'admin_delete_log', 'admin_list_blocks', 'admin_create_block', 'admin_update_block', 'admin_delete_block', 'admin_list_security_events', 'admin_reset_rate_limits', 'admin_list_rate_limits', 'admin_list_route_limits', 'admin_save_route_limit', 'admin_delete_route_limit', 'admin_list_repeat_offenders', 'admin_get_cache_settings', 'admin_save_cache_settings', 'admin_clear_cache', 'admin_list_allowlist', 'admin_create_allowlist_entry', 'admin_delete_allowlist_entry' );
	private QuoteLogStorage $logs; private LocationService $locations; private OperationalClock $clock; private SecurityLists $lists; private SecurityRateLimiter $limiter; private SecurityRouteLimits $limits;
	public function __construct( ?LocationService $locations = null, ?OperationalClock $clock = null, ?SecurityRateLimiter $limiter = null ) { $this->clock = $clock ?? new OperationalClock(); $this->locations = $locations ?? new LocationService(); $this->logs = new QuoteLogStorage( $this->clock ); $this->lists = new SecurityLists( new WordPressSecurityStateStore(), $this->clock ); $this->limits = new SecurityRouteLimits(); [$max, $window] = $this->limits->effective(); $this->limiter = $limiter ?? new SecurityRateLimiter( new WordPressRateLimitStore(), $this->clock, $max, $window, array( $this->limits, 'resolve' ), array( SecurityRouteLimits::class, 'normalize' ) ); }
	private function event( string $kind, string $detail ): void { try { SecurityEventStorage::record( new SecurityEvent( array( 'created_at_ms' => SecurityTime::milliseconds( $this->clock ), 'kind' => $kind, 'route' => '/api/admin/security/blocks', 'detail' => $detail ) ) ); } catch ( \Throwable $error ) {} }
	public function call( string $op, RestInput $input ): RestResult {
		if ( 'admin_list_logs' === $op ) { $from = $input->text( 'from' ); $to = $input->text( 'to' ); foreach ( array( 'from' => $from, 'to' => $to ) as $key => $date ) { if ( '' !== $date && ! preg_match( '/^\p{Nd}{4}-\p{Nd}{2}-\p{Nd}{2}$/uD', $date ) ) { throw new QuoteError( 400, 'قالب تاریخ ' . $key . ' نامعتبر است (YYYY-MM-DD).' ); } } if ( '' !== $from && '' !== $to && strcmp( $from, $to ) > 0 ) { throw new QuoteError( 400, 'تاریخ شروع نباید بعد از تاریخ پایان باشد.' ); } $provider = V::fallback( $input->text( 'provider' ), null ); return new RestResult( array( 'logs' => $this->logs->list_rows( min( max( $input->number( 'limit', 100 ), 1 ), 500 ), $provider, '' !== $from ? $from . 'T00:00:00' : null, '' !== $to ? $to . 'T23:59:59' : null, 'error' ), 'filters' => array( 'provider' => V::fallback( $provider, '' ), 'from' => $from, 'to' => $to ) ) ); }
		if ( 'admin_clear_logs' === $op ) { return new RestResult( array( 'deleted' => $this->logs->clear() ) ); }
		if ( 'admin_delete_log' === $op ) { $id = V::integer( $input->path['log_id'] ); if ( ! $this->logs->delete( $id ) ) { throw new QuoteError( 404, 'گزارش مورد نظر یافت نشد.' ); } return new RestResult( array( 'id' => $id, 'detail' => 'حذف شد.' ) ); }
		if ( 'admin_get_cache_settings' === $op ) { $settings = CacheSettings::get(); try { $stats = OperationalStats::get(); } catch ( \Throwable $error ) { $stats = array( 'price_rows' => 0, 'quote_logs_rows' => 0, 'security_events_rows' => 0 ); } try { $info = $this->locations->cache_info(); } catch ( \Throwable $error ) { $info = null; } $state = array( 'cached' => false ); if ( null !== $info ) { $cities = V::get( $info['payload'], 'cities' ); $state = array( 'cached' => true, 'fetched_at' => $info['fetched_at'], 'city_count' => V::listing( $cities ) ? count( $cities ) : 0 ); } return new RestResult( array( 'settings' => $settings, 'defaults' => CacheSettings::defaults(), 'stats' => $stats, 'locations' => $state ) ); }
		if ( 'admin_save_cache_settings' === $op ) { try { $settings = CacheSettings::save( $input->body() ); } catch ( \InvalidArgumentException $error ) { throw new QuoteError( 422, $error->getMessage() ); } return new RestResult( array( 'settings' => $settings, 'defaults' => CacheSettings::defaults(), 'detail' => 'ذخیره شد.' ) ); }
		if ( 'admin_clear_cache' === $op ) { $kind = V::text( V::fallback( $input->query['kind'] ?? null, 'price' ) ); $price = 0; if ( 'price' === $kind || 'all' === $kind ) { $price = ( new PriceCacheStorage() )->clear(); } if ( 'locations' === $kind || 'all' === $kind ) { $this->locations->clear(); if ( 'locations' === $kind ) { return new RestResult( array( 'cleared' => 1 ) ); } } if ( in_array( $kind, array( 'quote_logs', 'logs', 'all' ), true ) ) { $logs = $this->logs->clear(); } if ( in_array( $kind, array( 'security_events', 'security', 'all' ), true ) ) { $events = SecurityEventStorage::clear(); } if ( 'all' === $kind ) { return new RestResult( array( 'cleared' => $price + $logs + $events, 'detail' => array( 'price' => $price, 'quote_logs' => $logs, 'security_events' => $events, 'locations' => 1 ) ) ); } if ( ! in_array( $kind, array( 'price', 'quote_logs', 'logs', 'security_events', 'security' ), true ) ) { throw new QuoteError( 400, 'نوع کش نامعتبر است.' ); } return new RestResult( array( 'cleared' => $price + ( $logs ?? 0 ) + ( $events ?? 0 ) ) ); }
		if ( 'admin_list_blocks' === $op ) { return new RestResult( array( 'blocks' => $this->lists->blocks( $input->text( 'q' ), $input->text( 'type' ), $input->text( 'active' ), $input->number( 'limit', 200 ) ) ) ); }
		if ( 'admin_create_block' === $op ) { $body = $input->body(); try { $entry = $this->lists->block( V::text( V::fallback( V::get( $body, 'type' ), '' ) ), V::get( $body, 'value' ), V::get( $body, 'reason' ), V::get( $body, 'created_by' ), V::get( $body, 'expires_at_ms' ) ); } catch ( \InvalidArgumentException $error ) { throw new QuoteError( 422, $error->getMessage() ); } $this->event( 'admin_block', $entry->type . '=' . $entry->value . ' by ' . V::fallback( $entry->created_by, 'admin' ) ); return new RestResult( array( 'block' => $entry ), 201 ); }
		if ( 'admin_update_block' === $op || 'admin_delete_block' === $op ) { $id = V::integer( $input->path['block_id'] ); if ( 'admin_delete_block' === $op ) { $ok = $this->lists->delete( $id ); $body = array( 'id' => $id, 'detail' => 'حذف شد.' ); } else { $raw = $input->body(); if ( V::has( $raw, 'is_active' ) ) { $active = V::truth( $raw->is_active ); $ok = $active ? $this->lists->reactivate( $id ) : $this->lists->unblock( $id ); $body = array( 'id' => $id, 'is_active' => $active ); if ( $ok ) { $this->event( $active ? 'admin_block' : 'admin_unblock', 'id=' . $id . ' active=' . V::string( $active ) ); } } else { $ok = $this->lists->update( $id, V::get( $raw, 'reason' ), V::get( $raw, 'expires_at_ms' ) ); $body = array( 'id' => $id, 'detail' => 'ذخیره شد.' ); } } if ( ! $ok ) { throw new QuoteError( 404, 'رکورد مسدودیت یافت نشد.' ); } return new RestResult( $body ); }
		if ( 'admin_list_allowlist' === $op ) { return new RestResult( array( 'allowlist' => $this->lists->allowlist( $input->text( 'q' ), $input->number( 'limit', 200 ) ) ) ); }
		if ( 'admin_create_allowlist_entry' === $op ) { $body = $input->body(); try { $entry = $this->lists->allow( V::get( $body, 'ip' ), V::get( $body, 'reason' ), V::get( $body, 'created_by' ) ); } catch ( \InvalidArgumentException $error ) { throw new QuoteError( 422, $error->getMessage() ); } return new RestResult( array( 'entry' => $entry ), 201 ); }
		if ( 'admin_delete_allowlist_entry' === $op ) { $id = V::integer( $input->path['entry_id'] ); if ( ! $this->lists->remove_allow( $id ) ) { throw new QuoteError( 404, 'رکورد مجاز یافت نشد.' ); } return new RestResult( array( 'id' => $id, 'detail' => 'حذف شد.' ) ); }
		if ( 'admin_list_security_events' === $op ) { return new RestResult( array( 'events' => SecurityEventStorage::list_rows( $input->text( 'kind' ), $input->text( 'value' ), $input->number( 'limit', 200 ) ) ) ); }
		if ( 'admin_list_route_limits' === $op ) { $rows = array(); $overrides = ( new RouteLimitStorage() )->get(); foreach ( SecurityReports::catalog()['PUBLIC_API_CATALOG'] as $route => $entry ) { $rows[] = SecurityReports::entry( $route, $overrides ); } return new RestResult( array( 'routes' => $rows, 'admin_groups' => SecurityReports::catalog()['ADMIN_API_GROUPS'] ) ); }
		if ( 'admin_save_route_limit' === $op ) { $body = $input->body(); $route = SecurityRouteLimits::normalize( V::string( V::fallback( V::get( $body, 'route' ), '' ) ) ); if ( ! isset( SecurityRouteLimits::DEFAULTS[$route] ) ) { throw new QuoteError( 422, 'برای این مسیر نمی‌توان محدودیت اختصاصی ثبت کرد.' ); } try { $saved = ( new RouteLimitStorage( $this->clock ) )->save( $route, V::get( $body, 'max_requests' ), V::get( $body, 'window_seconds' ), V::get( $body, 'enabled', true ) ); } catch ( \InvalidArgumentException $error ) { throw new QuoteError( 422, $error->getMessage() ); } return new RestResult( array( 'route' => SecurityReports::entry( $route, (object) array( $route => (object) $saved ) ), 'detail' => 'ذخیره شد.' ) ); }
		if ( 'admin_delete_route_limit' === $op ) { $route = SecurityRouteLimits::normalize( $input->text( 'route' ) ); if ( ! isset( SecurityReports::catalog()['PUBLIC_API_CATALOG'][$route] ) ) { throw new QuoteError( 422, 'مسیر API معتبر نیست.' ); } ( new RouteLimitStorage() )->delete( $route ); return new RestResult( array( 'route' => $route, 'detail' => 'به حد پیش‌فرض برگشت.' ) ); }
		if ( 'admin_reset_rate_limits' === $op ) { if ( '1' === $input->text( 'all' ) ) { $this->limiter->reset_all(); return new RestResult( array( 'detail' => 'محدودیت همه برداشته شد.', 'reset' => 'all' ) ); } $ip = $input->text( 'ip' ); $id = $input->text( 'client_id' ); $fp = $input->text( 'fingerprint' ); if ( '' === $ip && '' === $id && '' === $fp ) { throw new QuoteError( 422, 'حداقل یک شناسه (ip، client_id یا fingerprint) یا all=1 لازم است.' ); } $route = $input->text( 'route' ); if ( '' !== $route ) { $route = SecurityRouteLimits::normalize( $route ); if ( ! isset( SecurityRouteLimits::DEFAULTS[$route] ) ) { throw new QuoteError( 422, 'مسیر API معتبر نیست.' ); } $this->limiter->reset_identity( $ip, $id, $fp, $route ); } else { foreach ( array_keys( SecurityRouteLimits::DEFAULTS ) as $route ) { $this->limiter->reset_identity( $ip, $id, $fp, $route ); } } return new RestResult( array( 'detail' => '' !== $input->text( 'route' ) ? 'محدودیت این مورد در این API برداشته شد.' : 'محدودیت برداشته شد.', 'reset' => 'identity' ) ); }
		$reports = new SecurityReports( $this->limiter, $this->limits, $this->clock ); if ( 'admin_list_rate_limits' === $op ) { return new RestResult( $reports->active( $input->text( 'q' ), $input->number( 'limit', 100 ) ) ); } if ( 'admin_list_repeat_offenders' === $op ) { return new RestResult( $reports->offenders( $input->text( 'q' ), $input->number( 'limit', 100 ), $input->number( 'min', 5 ) ) ); }
		throw new \LogicException( 'Unknown operational operation.' );
	}
}
